<?php require __DIR__.'/../config/database.php';
// Jalankan sekali untuk membuat akun admin pertama, lalu HAPUS file setup.php dari server.
$count=(int)$conn->query('SELECT COUNT(*) n FROM admins')->fetch_assoc()['n'];$error='';$done=false;
if($_SERVER['REQUEST_METHOD']==='POST'&&$count===0){$name=trim($_POST['name']??'');$user=trim($_POST['username']??'');$pass=$_POST['password']??'';if($name===''||!preg_match('/^[A-Za-z0-9_.-]{4,60}$/',$user)||strlen($pass)<12){$error='Isi nama, username 4–60 karakter (huruf/angka/._-), dan password minimal 12 karakter.';}else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO admins(name,username,password_hash) VALUES(?,?,?)');$s->bind_param('sss',$name,$user,$hash);$s->execute();$done=true;}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup Admin</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="login-page"><section class="login-card"><a class="brand" href="../index.php"><span class="brand-mark">N</span>Nusindo Wisata.</a><h1>Buat admin pertama</h1><?php if($count>0&&!$done):?><div class="notice">Akun admin sudah tersedia. Demi keamanan, hapus file <code>admin/setup.php</code> dari server dan masuk melalui halaman login.</div><a class="btn btn-primary" href="login.php">Ke Login Admin</a><?php elseif($done):?><div class="notice">Admin berhasil dibuat. Sekarang hapus file <code>admin/setup.php</code> dari server.</div><a class="btn btn-primary" href="login.php">Login Admin</a><?php else:?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><p class="muted">Setup hanya tersedia sebelum akun admin pertama dibuat.</p><form method="post"><div class="field" style="margin:15px 0"><label>Nama admin</label><input name="name" required></div><div class="field" style="margin:15px 0"><label>Username</label><input name="username" required minlength="4" maxlength="60" autocomplete="username"></div><div class="field" style="margin:15px 0"><label>Password (minimal 12 karakter)</label><input name="password" type="password" required minlength="12" autocomplete="new-password"></div><button class="btn btn-primary" style="width:100%">Buat Akun Admin</button></form><?php endif;?></section></body></html>
